package com.ejemplo.alquileres.seeder;
import com.ejemplo.alquileres.model.*; import com.ejemplo.alquileres.repository.PropietarioRepository; import com.ejemplo.alquileres.service.PropietarioService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class PropietarioSeeder {private final PropietarioRepository repo;private final PropietarioService service;
 public void cargar(){crear(TipoDocumento.DNI,"45671234","María Elena Salazar","999 111 222");crear(TipoDocumento.RUC,"20123456789","Inversiones Costa Sur S.A.C.","+51 988 333 444");} private void crear(TipoDocumento t,String d,String n,String tel){if(!repo.existsByTipoDocumentoAndNumeroDocumento(t,d))service.guardar(Propietario.builder().tipoDocumento(t).numeroDocumento(d).nombre(n).telefono(tel).email("contacto@ejemplo.pe").banco("BCP").cuenta("CCI ficticia").activo(true).build());}}
